import { Component, computed, effect, inject, input, output, signal, untracked } from '@angular/core';
import { InvoiceDetail, InvoiceService, InvoiceSummary, NewAllocation } from './invoice.service';
import { PaymentForm } from './payment-form';
import { RefundForm } from './refund-form';
import { InvoicePanel } from './invoice-panel';
import { Currency, money, statusLabel, symbolOf } from './invoice-format';

// One client's invoices, each with its status, total, issue and due dates. Clicking an invoice
// opens it in the invoice panel beside the list; New invoice starts an empty draft and opens it.
// An invoice looked up by its number is opened as soon as its client's invoices are shown.
// Every sent invoice that is not void has a box for its part of a payment; once any is filled, the payment recorded
// (in the panel, or below the list when no invoice is open) is spread over those invoices.
// The client's unused credit can be refunded from the refund form below the list.
@Component({
  selector: 'app-client-invoices',
  imports: [InvoicePanel, PaymentForm, RefundForm],
  styles: `
    :host {
      display: flex;
      flex-wrap: wrap;
      gap: 2rem;
      align-items: flex-start;
    }
    tr[aria-selected='true'] {
      font-weight: bold;
    }
    .allocate {
      width: 6rem;
    }
    .open {
      font: inherit;
      color: inherit;
      background: none;
      border: none;
      padding: 0;
      cursor: pointer;
      text-decoration: underline;
    }
  `,
  template: `
    <section aria-labelledby="invoices-heading">
      <h2 id="invoices-heading">Invoices for {{ clientName() }}</h2>
      <button type="button" data-testid="invoice-new" [disabled]="creating()" (click)="newDraft()">
        New invoice
      </button>
      <button type="button" data-testid="invoice-send-all" [disabled]="sendingAll()" (click)="sendAllDrafts()">
        Send all drafts
      </button>
      <table data-testid="invoice-list">
        <thead>
          <tr>
            <th scope="col">Invoice</th>
            <th scope="col">Status</th>
            <th scope="col">Total</th>
            <th scope="col">Issued</th>
            <th scope="col">Due</th>
            <th scope="col">Part of payment ({{ symbolOf(currency()) }})</th>
          </tr>
        </thead>
        <tbody>
          @for (i of invoices(); track i.id) {
            <tr
              [attr.data-testid]="'invoice-row-' + i.id"
              [attr.aria-selected]="selectedId() === i.id"
              (click)="selectedId.set(i.id)"
            >
              <td>
                <button
                  type="button"
                  class="open"
                  (click)="$event.stopPropagation(); selectedId.set(i.id)"
                >
                  <span data-testid="invoice-number">{{ i.number }}</span>
                </button>
              </td>
              <td data-testid="invoice-status">{{ statusLabel(i.status) }}</td>
              <td data-testid="invoice-total">{{ money(i.total, currency()) }}</td>
              <td data-testid="invoice-issue">{{ i.issueDate }}</td>
              <td data-testid="invoice-due">{{ i.dueDate }}</td>
              <td>
                @if (i.status !== 'DRAFT' && i.status !== 'VOID' && i.status !== 'CREDIT_NOTE') {
                  <input
                    class="allocate"
                    data-testid="invoice-allocate"
                    inputmode="decimal"
                    [attr.aria-label]="'Part of payment for ' + i.number"
                    [value]="allocated()[i.id] ?? ''"
                    (click)="$event.stopPropagation()"
                    (input)="allocate(i.id, $any($event.target).value)"
                  />
                }
              </td>
            </tr>
          } @empty {
            <tr>
              <td colspan="6" data-testid="invoice-empty">No invoices yet.</td>
            </tr>
          }
        </tbody>
      </table>
      <app-refund-form [clientId]="clientId()" [currency]="currency()" (refunded)="splitRecorded($event)" />
    </section>

    @if (selectedId(); as id) {
      <app-invoice-panel
        [invoiceId]="id"
        [reload]="reloadPanel()"
        [allocations]="allocations()"
        (changed)="totalChanged($event)"
        (split)="splitRecorded($event)"
        (duplicated)="duplicated($event)"
        (credited)="duplicated($event)"
      />
    } @else if (invoices().length > 0) {
      <app-payment-form
        [clientId]="clientId()"
        [currency]="currency()"
        [allocations]="allocations()"
        (split)="splitRecorded($event)"
        (deposited)="splitRecorded($event)"
      />
    }
  `,
})
export class ClientInvoices {
  private readonly service = inject(InvoiceService);

  readonly clientId = input.required<number>();
  readonly clientName = input('');
  // The currency the client is billed in, which its invoices' amounts are in.
  readonly currency = input<Currency>('USD');
  // An invoice to open, looked up by number; a new object for each lookup, so the same invoice
  // can be opened again.
  readonly openInvoice = input<{ id: number; clientId: number } | null>(null);

  // An invoice of the client was changed or paid, so what the client owes may have changed.
  readonly changed = output<void>();

  protected readonly invoices = signal<InvoiceSummary[]>([]);
  protected readonly selectedId = signal<number | null>(null);
  protected readonly creating = signal(false);
  protected readonly sendingAll = signal(false);
  // Bumped to make the invoice panel load its invoice again.
  protected readonly reloadPanel = signal(0);
  // The part of a payment typed for each invoice, by id, as entered.
  protected readonly allocated = signal<Record<number, string>>({});
  // The parts that have been filled in, for the payment form.
  protected readonly allocations = computed<NewAllocation[]>(() =>
    Object.entries(this.allocated())
      .map(([id, amount]) => ({ invoiceId: Number(id), amount: amount.trim().replace(/^\$/, '') }))
      .filter((a) => a.amount !== ''),
  );
  protected readonly statusLabel = statusLabel;
  protected readonly money = money;
  protected readonly symbolOf = symbolOf;

  constructor() {
    effect((onCleanup) => {
      const id = this.clientId();
      this.invoices.set([]);
      this.allocated.set({});
      const open = untracked(this.openInvoice);
      this.selectedId.set(open?.clientId === id ? open.id : null);
      const sub = this.service.forClient(id).subscribe((list) => this.invoices.set(list));
      onCleanup(() => sub.unsubscribe());
    });
    effect(() => {
      const open = this.openInvoice();
      if (open && open.clientId === untracked(this.clientId)) {
        this.selectedId.set(open.id);
      }
    });
  }

  protected newDraft(): void {
    this.creating.set(true);
    this.service.newDraft(this.clientId()).subscribe({
      next: (created) => {
        this.invoices.update((list) => [...list, created]);
        this.selectedId.set(created.id);
        this.creating.set(false);
      },
      error: () => this.creating.set(false),
    });
  }

  // Sends every draft with lines: show their new statuses and dates, and load the open invoice
  // again so the panel shows it as sent.
  protected sendAllDrafts(): void {
    this.sendingAll.set(true);
    this.service.sendAllDrafts(this.clientId()).subscribe({
      next: (list) => {
        this.invoices.set(list);
        this.reloadPanel.update((n) => n + 1);
        this.sendingAll.set(false);
        this.changed.emit();
      },
      error: () => this.sendingAll.set(false),
    });
  }

  // An invoice was duplicated or credited: list the new draft and open it.
  protected duplicated(detail: InvoiceDetail): void {
    const { id, number, status, listedTotal, issueDate, listedDueDate, creditOf } = detail;
    this.invoices.update((list) => [
      ...list,
      { id, number, status, total: listedTotal, issueDate, dueDate: listedDueDate, creditOf },
    ]);
    this.selectedId.set(id);
  }

  protected allocate(invoiceId: number, amount: string): void {
    this.allocated.update((parts) => ({ ...parts, [invoiceId]: amount }));
  }

  // A payment was spread over several invoices: show their new statuses and clear the parts.
  protected splitRecorded(list: InvoiceSummary[]): void {
    this.invoices.set(list);
    this.allocated.set({});
    this.changed.emit();
  }

  // An invoice changed in the panel: show its new status, dates and total in the list.
  protected totalChanged(detail: InvoiceDetail): void {
    this.invoices.update((list) =>
      list.map((i) =>
        i.id === detail.id
          ? {
              ...i,
              status: detail.status,
              issueDate: detail.issueDate,
              dueDate: detail.listedDueDate,
              total: detail.listedTotal,
            }
          : i,
      ),
    );
    this.changed.emit();
  }
}
import { Component, effect, inject, input, output, signal } from '@angular/core';
import { toSignal } from '@angular/core/rxjs-interop';
import { HttpErrorResponse } from '@angular/common/http';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import {
  InvoiceDetail,
  InvoiceService,
  InvoiceSummary,
  NewAllocation,
  NewPayment,
} from './invoice.service';
import { CURRENCIES, Currency, TWO_DECIMALS, cents, symbolOf } from './invoice-format';

// Whether a reference passes the ISO 11649 check: its first four characters moved to the end,
// letters as numbers (A=10 up to Z=35), mod 97 is 1. Spaces and capitals are ignored by the caller.
function referenceChecks(reference: string): boolean {
  if (!/^RF\d{2}[A-Z0-9]{1,21}$/.test(reference)) {
    return false;
  }
  const moved = reference.slice(4) + reference.slice(0, 4);
  let rest = 0;
  for (const c of moved) {
    for (const d of String(parseInt(c, 36))) {
      rest = (rest * 10 + Number(d)) % 97;
    }
  }
  return rest === 1;
}

// Whether an invoice number quoted instead of a reference (INV-, six digits, then a Luhn check
// digit over them) passes its check. Spaces and capitals are ignored by the caller.
function invoiceNumberChecks(typed: string): boolean {
  const m = /^INV-(\d{6})(\d)$/.exec(typed);
  if (!m) {
    return false;
  }
  let sum = 0;
  [...m[1]].reverse().forEach((c, i) => {
    let d = Number(c);
    if (i % 2 === 0) {
      d *= 2;
      if (d > 9) {
        d -= 9;
      }
    }
    sum += d;
  });
  return (10 - (sum % 10)) % 10 === Number(m[2]);
}

// Whether a typed reference (an RF reference or an invoice number) passes its check.
function quotedReferenceChecks(reference: string): boolean {
  return reference.startsWith('INV') ? invoiceNumberChecks(reference) : referenceChecks(reference);
}

// What is wrong with a payment, or '' when it can be recorded. With `several` the reference box may
// hold several references separated by commas, each checked on its own.
function problemWithPayment(payment: NewPayment, several: boolean): string {
  const problems: string[] = [];
  if (!payment.amount) {
    problems.push('Enter an amount.');
  } else if (!TWO_DECIMALS.test(payment.amount)) {
    problems.push('The amount must be a number with at most two decimals.');
  } else if (Number(payment.amount) <= 0) {
    problems.push('The amount must be more than zero.');
  }
  if (!/^\d{4}-\d{2}-\d{2}$/.test(payment.date)) {
    problems.push('Enter the date it was paid.');
  }
  const quoted = several
    ? payment.reference.split(',').filter((r) => r)
    : payment.reference
      ? [payment.reference]
      : [];
  const mistyped = quoted.filter((r) => !quotedReferenceChecks(r));
  if (mistyped.length > 0) {
    problems.push(
      quoted.length > 1
        ? `Mistyped payment reference: ${mistyped.join(', ')}. Check it against the invoice.`
        : 'The payment reference is mistyped: check it against the invoice.',
    );
  }
  return problems.join(' ');
}

// What is wrong with the parts of a split payment, or '' when they fit it. Whether each part is no
// more than its invoice has due is checked by the server, as is whether they add up to a payment made
// in another currency than the client's (`currency`) once converted.
function problemWithAllocations(payment: NewPayment, allocations: NewAllocation[], currency: Currency): string {
  if (allocations.some((a) => !TWO_DECIMALS.test(a.amount))) {
    return "Each invoice's part must be a number with at most two decimals.";
  }
  if (allocations.some((a) => cents(a.amount) <= 0)) {
    return "Each invoice's part must be more than zero.";
  }
  const sum = allocations.reduce((total, a) => total + cents(a.amount), 0);
  if (payment.currency === currency && TWO_DECIMALS.test(payment.amount) && sum !== cents(payment.amount)) {
    return `The parts add up to $${(sum / 100).toFixed(2)}, not the $${(cents(payment.amount) / 100).toFixed(2)} paid.`;
  }
  return '';
}

// Records a payment. With no parts filled in it goes to the open invoice (`invoiceId`), or, when none
// is open, to the client's invoices whose references are quoted (several may be, separated by
// commas: RF references or invoice numbers, applied overdue first, then largest due first), or without one to the client's unpaid invoices in that order; once any invoice in the list has a part, the
// payment is spread over those invoices instead, and the parts must add up to it, none over what its invoice has due. Otherwise what is paid beyond
// what is due is held on the client's account as credit. The server refuses a payment on a draft, or dated after today
// or before the issue date; a quoted reference must pass the ISO 11649 check and be the invoice's. The
// invoice number may be quoted instead: it must pass its Luhn check and stands for that invoice's reference.
// Ticking Deposit instead holds the whole amount on the client's account as credit, applied to no
// invoice even when one is open; the client's credit is used when one of its invoices is sent. A
// deposit quoting one of the client's drafts is held for that draft until it is sent.
@Component({
  selector: 'app-payment-form',
  imports: [ReactiveFormsModule],
  template: `
    <form [formGroup]="form" (ngSubmit)="record()" aria-label="Record a payment" novalidate>
      <label for="payment-currency">Paid in</label>
      <select id="payment-currency" data-testid="payment-form-currency" formControlName="currency">
        @for (c of currencies; track c) {
          <option [value]="c">{{ c }}</option>
        }
      </select>
      <label for="payment-amount">Amount ({{ symbolOf(paidIn()) }})</label>
      <input
        id="payment-amount"
        data-testid="payment-form-amount"
        inputmode="decimal"
        formControlName="amount"
        required
      />
      <label for="payment-date">Paid on</label>
      <input
        id="payment-date"
        type="date"
        data-testid="payment-form-date"
        formControlName="date"
        required
      />
      <label for="payment-reference">
        @if (invoiceId() === null) {
          References or invoice numbers quoted, separated by commas (optional)
        } @else {
          Reference or invoice number quoted (optional)
        }
      </label>
      <input
        id="payment-reference"
        data-testid="payment-form-reference"
        formControlName="reference"
        autocapitalize="characters"
        placeholder="RF16 0000 075"
      />
      <input
        id="payment-deposit"
        type="checkbox"
        data-testid="payment-form-deposit"
        formControlName="deposit"
      />
      <label for="payment-deposit"
        >Deposit (hold as credit on the client's account; quote a draft's reference to hold it for that invoice)</label
      >
      <button type="submit" data-testid="payment-form-submit" [disabled]="saving()">
        Record payment
      </button>
      @if (error()) {
        <p role="alert" data-testid="payment-form-error">{{ error() }}</p>
      }
    </form>
  `,
})
export class PaymentForm {
  private readonly service = inject(InvoiceService);

  readonly clientId = input.required<number>();
  // The currency the client is billed in: the payment's by default. A payment in another currency is
  // converted into it by the server at the workspace rates in force on the payment date (whole yen
  // for yen; the server checks).
  readonly currency = input<Currency>('USD');
  protected readonly symbolOf = symbolOf;
  protected readonly currencies = CURRENCIES;
  // The open invoice, which takes the payment when no parts are filled in; null when none is open.
  readonly invoiceId = input<number | null>(null);
  readonly allocations = input<NewAllocation[]>([]);
  // The open invoice after a payment to it alone.
  readonly paid = output<InvoiceDetail>();
  // The client's invoices after a payment spread over several of them.
  readonly split = output<InvoiceSummary[]>();
  // The client's invoices after a deposit held as credit.
  readonly deposited = output<InvoiceSummary[]>();

  protected readonly saving = signal(false);
  protected readonly error = signal('');

  protected readonly form = new FormGroup({
    amount: new FormControl('', { nonNullable: true }),
    date: new FormControl('', { nonNullable: true }),
    reference: new FormControl('', { nonNullable: true }),
    deposit: new FormControl(false, { nonNullable: true }),
    currency: new FormControl<Currency>('USD', { nonNullable: true }),
  });
  // The currency picked to pay in, as a signal for the amount's label.
  protected readonly paidIn = toSignal(this.form.controls.currency.valueChanges, {
    initialValue: this.form.controls.currency.value,
  });

  constructor() {
    // Each new client (or invoice) starts with its own currency picked.
    effect(() => this.resetCurrency(this.currency()));
  }

  private resetCurrency(currency: Currency): void {
    this.form.controls.currency.setValue(currency);
  }

  protected record(): void {
    const raw = this.form.getRawValue();
    const payment: NewPayment = {
      amount: raw.amount.trim().replace(/^\$/, ''),
      currency: raw.currency,
      date: raw.date.trim(),
      reference: raw.reference.replace(/\s/g, '').toUpperCase(),
    };
    if (raw.deposit) {
      this.recordDeposit(payment);
      return;
    }
    const allocations = this.allocations();
    const invoiceId = this.invoiceId();
    let problem = problemWithPayment(payment, allocations.length === 0 && invoiceId === null);
    if (allocations.length > 0) {
      problem = [problem, problemWithAllocations(payment, allocations, this.currency())].filter((p) => p).join(' ');
    }
    if (problem) {
      this.form.markAllAsTouched();
      this.error.set(problem);
      return;
    }
    this.saving.set(true);
    this.error.set('');
    const done = () => {
      this.form.reset({ currency: this.currency() });
      this.saving.set(false);
    };
    const failed = (e: HttpErrorResponse) => {
      const detail: unknown = e.error?.detail;
      this.error.set(
        typeof detail === 'string' && detail ? detail : 'The payment could not be recorded.',
      );
      this.saving.set(false);
    };
    if (allocations.length > 0 || invoiceId === null) {
      this.service
        .recordSplitPayment(this.clientId(), { ...payment, allocations })
        .subscribe({
          next: (list) => {
            done();
            this.split.emit(list);
          },
          error: failed,
        });
    } else if (invoiceId !== null) {
      this.service
        .recordPayment(invoiceId, payment)
        .subscribe({
          next: (detail) => {
            done();
            this.paid.emit(detail);
          },
          error: failed,
        });
    }
  }

  // Records the whole payment as a deposit, credit on the client's account. With a reference (an RF
  // reference or invoice number of one of the client's drafts; the server refuses any other) it is held
  // for that invoice: used first when it is sent, and by nothing else until then.
  private recordDeposit(payment: NewPayment): void {
    const problem = problemWithPayment(payment, false);
    if (problem) {
      this.form.markAllAsTouched();
      this.error.set(problem);
      return;
    }
    this.saving.set(true);
    this.error.set('');
    this.service
      .recordDeposit(this.clientId(), {
        amount: payment.amount,
        currency: payment.currency,
        date: payment.date,
        reference: payment.reference || undefined,
      })
      .subscribe({
        next: (list) => {
          this.form.reset({ currency: this.currency() });
          this.saving.set(false);
          this.deposited.emit(list);
        },
        error: (e: HttpErrorResponse) => {
          const detail: unknown = e.error?.detail;
          this.error.set(
            typeof detail === 'string' && detail ? detail : 'The deposit could not be recorded.',
          );
          this.saving.set(false);
        },
      });
  }
}
